    public virtual void handleMyTrades(WebSocketClient client, Dictionary<string, object> message)
    {
        //
        //     {
        //         "channel": "userFills",
        //         "data": {
        //             "isSnapshot": true,
        //             "user": "0x15f43d1f2dee81424afd891943262aa90f22cc2a",
        //             "fills": [
        //                 {
        //                     "coin": "BTC",
        //                     "px": "72528.0",
        //                     "sz": "0.11693",
        //                     "side": "A",
        //                     "time": 1710208712815,
        //                     "startPosition": "0.11693",
        //                     "dir": "Close Long",
        //                     "closedPnl": "-0.81851",
        //                     "hash": "0xc5adaf35f8402750c218040b0a7bc301130051521273b6f398b3caad3e1f3f5f",
        //                     "oid": 7484888874,
        //                     "crossed": true,
        //                     "fee": "2.968244",
        //                     "liquidationMarkPx": null,
        //                     "tid": 567547935839686,
        //                     "cloid": null
        //                 }
        //             ]
        //         }
        //     }
        //
        IDictionary<string, object> entry = this.safeDict(message, "data", new Dictionary<string, object>() {});
        if ((this.myTrades == null))
        {
            Int64? limit = this.safeInteger(this.options, "tradesLimit", 1000);
            this.myTrades = new ArrayCacheBySymbolById(limit);
        }
        ccxt.pro.ArrayCache trades = this.myTrades;
        Dictionary<string, object> symbols = new Dictionary<string, object>() {};
        List<object> data = this.safeList(entry, "fills", new List<object>() {});
        int dataLength = data.Count;
        if ((dataLength == 0))
        {
            return;
        }
        for (int i = 0; i < data.Count; i++)
        {
            object rawTrade = data[i];
            Dictionary<string, object> parsed = this.parseWsTrade(rawTrade);
            string? symbol = ((string)(parsed != null && ((IDictionary<string, object>)parsed).ContainsKey("symbol") ? ((IDictionary<string, object>)parsed)["symbol"] : null));
            symbols[(string)symbol] = true;
            trades.append(parsed);
        }
        List<object> keys = new List<object>(((IDictionary<string,object>)symbols).Keys);
        for (int i = 0; i < keys.Count; i++)
        {
            string currentMessageHash = ("myTrades:" + (keys[i]));
            client.resolve(trades, currentMessageHash);
        }
        // non-symbol specific
        string messageHash = "myTrades";
        client.resolve(trades, messageHash);
    }

