    public virtual void handleTrades(WebSocketClient client, Dictionary<string, object> message)
    {
        //
        //     {
        //         "channel": "trades",
        //         "data": [
        //             {
        //                 "coin": "BTC",
        //                 "side": "A",
        //                 "px": "68517.0",
        //                 "sz": "0.005",
        //                 "time": 1710125266669,
        //                 "hash": "0xc872699f116e012186620407fc08a802015e0097c5cce74710697f7272e6e959",
        //                 "tid": 981894269203506
        //             }
        //         ]
        //     }
        //
        List<object> entry = this.safeList(message, "data", new List<object>() {});
        int entryLength = entry.Count;
        if ((entryLength == 0))
        {
            return;
        }
        IDictionary<string, object> first = this.safeDict(entry, 0, new Dictionary<string, object>() {});
        string? coin = this.safeString(first, "coin");
        string? marketId = this.coinToMarketId(coin);
        Dictionary<string, object> market = this.market(marketId);
        string? symbol = ((string)(market.ContainsKey("symbol") ? market["symbol"] : null));
        if (!(inOp(this.trades, symbol)))
        {
            Int64? limit = this.safeInteger(this.options, "tradesLimit", 1000);
            var stored = new ArrayCache(limit);
            ((IDictionary<string,object>)this.trades)[(string)symbol] = stored;
        }
        ccxt.pro.ArrayCache trades = ((ccxt.pro.ArrayCache)getValue(this.trades, symbol));
        for (int i = 0; i < entry.Count; i++)
        {
            IDictionary<string, object> data = this.safeDict(entry, i, new Dictionary<string, object>() {});
            Dictionary<string, object> trade = this.parseWsTrade(data);
            trades.append(trade);
        }
        string messageHash = ("trade:" + symbol);
        client.resolve(trades, messageHash);
    }

    public override Dictionary<string, object> parseWsTrade(object trade, object market = null)
    {
        //
        // fetchMyTrades
        //
        //     {
        //         "coin": "BTC",
        //         "px": "72528.0",
        //         "sz": "0.11693",
        //         "side": "A",
        //         "time": 1710208712815,
        //         "startPosition": "0.11693",
        //         "dir": "Close Long",
        //         "closedPnl": "-0.81851",
        //         "hash": "0xc5adaf35f8402750c218040b0a7bc301130051521273b6f398b3caad3e1f3f5f",
        //         "oid": 7484888874,
        //         "crossed": true,
        //         "fee": "2.968244",
        //         "liquidationMarkPx": null,
        //         "tid": 567547935839686,
        //         "cloid": null
        //     }
        //
        // fetchTrades
        //
        //     {
        //         "coin": "BTC",
        //         "side": "A",
        //         "px": "68517.0",
        //         "sz": "0.005",
        //         "time": 1710125266669,
        //         "hash": "0xc872699f116e012186620407fc08a802015e0097c5cce74710697f7272e6e959",
        //         "tid": 981894269203506
        //     }
        //
        Int64? timestamp = this.safeInteger(trade, "time");
        string? price = this.safeString(trade, "px");
        string? amount = this.safeString(trade, "sz");
        string? coin = this.safeString(trade, "coin");
        string? marketId = this.coinToMarketId(coin);
        market = this.safeMarket(marketId);
        string? symbol = ((string)getValue(market, "symbol"));
        string? id = this.safeString(trade, "tid");
        string? side = this.safeString(trade, "side");
        if ((side != null))
        {
            side = (side == "A") ? "sell" : "buy";
        }
        string? fee = this.safeString(trade, "fee");
        return this.safeTrade(new Dictionary<string, object>() {
            { "info", trade },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "symbol", symbol },
            { "id", id },
            { "order", this.safeString(trade, "oid") },
            { "type", null },
            { "side", side },
            { "takerOrMaker", null },
            { "price", price },
            { "amount", amount },
            { "cost", null },
            { "fee", new Dictionary<string, object>() {
                { "cost", fee },
                { "currency", "USDC" },
            } },
        }, market);
    }

